import {globeDefaults,globeSources,validateGlobe} from './globe-opening.js?v=motion-v69';
export function mountGlobeControls(host,params,{save=()=>{},replace=()=>{},preview=()=>{}}={}){
 const box=document.createElement('details');box.className='directorSection';box.open=true;box.innerHTML='<summary>Globe opening · Earth, sky and light</summary>';host.append(box);
 const row=(parent,label,el)=>{const l=document.createElement('label');l.textContent=label;l.append(el);parent.append(l);};
 const button=(label,fn)=>{const b=document.createElement('button');b.type='button';b.className='pill';b.textContent=label;b.onclick=fn;box.append(b);};
 const check=(key,label,parent=box)=>{const el=document.createElement('input');el.type='checkbox';el.checked=params[key]??globeDefaults[key];el.onchange=()=>{params[key]=el.checked;save();};row(parent,label,el);};
 const number=(key,label,min,max,step,parent=box)=>{const i=document.createElement('input');Object.assign(i,{type:'number',min,max,step,value:params[key]??globeDefaults[key]});i.onchange=()=>{const n=Number(i.value);if(!Number.isFinite(n))return;const previous=params[key];params[key]=Math.max(min,Math.min(max,n));try{validateGlobe(params);save();}catch(e){params[key]=previous;i.value=previous??globeDefaults[key];status.textContent=e.message;}};row(parent,label,i);};
 check('globeEnabled','Use globe lead-in (off restores original opening)');for(const [t,label]of [[0,'opening'],[3,'spin and sky'],[5.5,'close approach'],[6.6,'cloud handoff']])button('Preview '+label,()=>preview(t));
 for(const [key,label,min,max,step]of [['globeLeadDuration','Approach duration (s)',1,20,.05],['globeSpinSpeed','Earth spin (degrees/s)',-30,30,.1],['globeSkySpeed','Sky drift (px/s)',-100,100,1],['globeRimStrength','Atmosphere / rim strength',0,3,.05],['globeFlashStrength','Flash intensity',0,2,.05]])number(key,label,min,max,step);
 const sources=document.createElement('details');sources.innerHTML='<summary>Replace Earth, night lights, sky or clouds</summary>';box.append(sources);for(const key of Object.keys(globeSources)){const b=document.createElement('button');b.type='button';b.textContent='Replace '+key.replace('globe','').replace(/([a-z])([A-Z])/g,'$1 $2')+'…';b.onclick=()=>replace(key);sources.append(b);}
 const advanced=document.createElement('details');advanced.innerHTML='<summary>Advanced · orientation, sky colors, flashes and camera</summary>';box.append(advanced);
 for(const [k,d]of Object.entries(globeDefaults))if(typeof d==='number'&&!['globeLeadDuration','globeSpinSpeed','globeSkySpeed','globeRimStrength','globeFlashStrength'].includes(k))number(k,k.replace('globe','').replace(/([a-z])([A-Z])/g,'$1 $2'),/Longitude|Latitude|Center/.test(k)?-960:/Fov/.test(k)?10:.01,/Fov/.test(k)?100:/Center/.test(k)?1600:/Longitude|Latitude/.test(k)?180:Math.max(10,d*4),.01,advanced);
 for(const key of ['globeSkyBlue','globeSkyRed']){const i=document.createElement('input');i.type='color';i.value=params[key]??globeDefaults[key];i.oninput=()=>{params[key]=i.value;save();};row(advanced,key==='globeSkyBlue'?'Blue field':'Red field',i);}
 for(const [key,label]of [['globeShowBrands','Show brand planes'],['globeShowClouds','Show cloud layers'],['globeShowFlashes','Enable flashes']])check(key,label,advanced);
 const keys=document.createElement('textarea');keys.value=JSON.stringify(params.globeRadiusKeys??globeDefaults.globeRadiusKeys);keys.setAttribute('aria-label','Camera approach radius keys [native seconds, stage-pixel radius]');advanced.append(keys);const apply=document.createElement('button');apply.type='button';apply.textContent='Apply approach keys';apply.onclick=()=>{try{const value=JSON.parse(keys.value);validateGlobe({...params,globeRadiusKeys:value});params.globeRadiusKeys=value;save();status.textContent='Approach curve applied';}catch(e){status.textContent=e.message;}};advanced.append(apply);
 const status=document.createElement('p');status.className='sub';box.append(status);return box;
}
